\begin{theorem}
\label{thm:lower}
For any sampling design $p$ with all $\pi_i>0$ and any unbiased estimator $\delta$,
\[
  \sup_{y\in\Theta}R(\delta,p;y)
  \geq
  \sum_{i=1}^N r_i^2\left( \frac{1-\pi_i}{\pi_i}\right).
\]
\end{theorem}
\begin{theorem}
\label{thm:sharpness}
Assume $r_i>0$ for all $i$. Fix a design $p$ with $\pi_i>0$ for all $i$. The following statements are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item there exists an unbiased estimator $\delta$ with
\[
  \sup_{y\in\Theta}R(\delta,p;y)=D_\pi;
\]
\item the midpoint-differenced estimator $\widehat T$ satisfies
\[
  \sup_{y\in\Theta}R(\widehat T,p;y)=D_\pi;
\]
\item $\Delta_{ij}=0$ for every $i\ne j$.
\end{enumerate}
\end{theorem}
\begin{theorem}
\label{thm:design}
Among all pairs $(p,\delta)$ in which $p$ is a sampling design such that $\pi_i >0$ for all $i$ and $\E_p[|S|]\leq n$, and $\delta$ is unbiased,
\[
  \inf_{p,\delta}\sup_{y\in\Theta}R(\delta,p;y)=V_n.
\]
The value $V_n$ is attained by using the estimator $\widehat T$ and sampling each unit independently with inclusion probabilities
\[
  \pi_i^*=\min(1,cr_i),
\]
where the constant $c>0$ is chosen so that $\sum_{i=1}^N\pi_i^*=n$.
\end{theorem}
